   pure subroutine one_e_grad_item_01(ij, nshell, nao, natm, maxnp, sh_l, sh_np, sh_ao, sh_at, sh_e, sh_c, sh_r, at_z, at_r, npair, p_i, p_j, wmat, dmat, nlane, gp)
      !$acc routine seq
      integer,  intent(in)  :: ij
      integer,  intent(in)  :: nshell, nao, natm, maxnp, npair, nlane
      integer,  intent(in)  :: p_i(npair), p_j(npair)
      integer,  intent(in)  :: sh_l(nshell), sh_np(nshell), sh_ao(nshell), sh_at(nshell)
      real(dp), intent(in)  :: sh_e(maxnp, nshell), sh_c(maxnp, nshell)
      real(dp), intent(in)  :: sh_r(3, nshell)
      real(dp), intent(in)  :: at_z(natm), at_r(3, natm)
      real(dp), intent(in)  :: wmat(nao, nao), dmat(nao, nao)
      real(dp), intent(inout) :: gp(3, natm, nlane)
      integer  :: ii, jj, a, c, mu, nu, lane
      real(dp) :: wt, ga(3), gb(3)
      real(dp) :: wblk(3), dblk(3)
      ii = p_i(ij); jj = p_j(ij)
      wt = merge(1.0_dp, 2.0_dp, ii == jj)
      lane = mod(ij - 1, nlane) + 1
      ! Affine index, not a running counter: nvfortran 26.5 fails "Missing
      ! increment value" on a counter used as a subscript in this loop nest
      ! (the same defect gen_df.py works around).
      do c = 0, 2
         nu = sh_ao(jj) + c
         do a = 0, 0
            mu = sh_ao(ii) + a
            wblk(1 + a + 1*c) = wmat(mu, nu)
            dblk(1 + a + 1*c) = dmat(mu, nu)
         end do
      end do
      call one_e_grad_01(sh_np(ii), sh_np(jj), sh_e(:, ii), sh_c(:, ii), sh_e(:, jj), sh_c(:, jj), &
                            sh_r(:, ii), sh_r(:, jj), natm, at_z, at_r, wt, wblk, dblk, ga, gb, &
                            gp(1:3, 1:natm, lane))
      ! ATOMIC, same reason as the gc write inside one_e_grad_01: two
      ! shell pairs sharing BOTH a lane and an atom (sh_at(ii) == sh_at
      ! (jj) of some OTHER pair) run this read-modify-write concurrently.
      ! Measured on the GPU: water/6-31G* (few shell pairs, so few same-lane,
      ! same-atom collisions) passed with this non-atomic; water/cc-pVDZ
      ! and formamide/cc-pVDZ (more shells, more collisions) did not --
      ! wrong by 0.1 to 11 Eh/Bohr, the same race signature (small, not
      ! huge, because most pairs still land cleanly) as the gc case before
      ! ITS atomic fix. The OpenMP port at 4 threads shows it on water/6-31G*
      ! too. Scalar statements because OpenACC atomic update does not take a
      ! vector/array-section target.
      !$acc atomic update
      gp(1, sh_at(ii), lane) = gp(1, sh_at(ii), lane) + ga(1)
      !$acc atomic update
      gp(2, sh_at(ii), lane) = gp(2, sh_at(ii), lane) + ga(2)
      !$acc atomic update
      gp(3, sh_at(ii), lane) = gp(3, sh_at(ii), lane) + ga(3)
      !$acc atomic update
      gp(1, sh_at(jj), lane) = gp(1, sh_at(jj), lane) + gb(1)
      !$acc atomic update
      gp(2, sh_at(jj), lane) = gp(2, sh_at(jj), lane) + gb(2)
      !$acc atomic update
      gp(3, sh_at(jj), lane) = gp(3, sh_at(jj), lane) + gb(3)
   end subroutine one_e_grad_item_01

   pure subroutine one_e_grad_01(nprim_a, nprim_b, ea, ca, eb, cb, ra, rb, &
                                    natm, zatm, ratm, wt, wblk, dblk, ga, gb, gc)
      !! (0|1) one-electron gradient block: -W:dS/dR, +D:dT/dR, and
      !! +D:dV/dR (basis derivative on A and B, Hellmann-Feynman on every
      !! nucleus), contracted straight into ga (bra atom), gb (ket atom)
      !! and gc (every atom) -- no derivative matrix is ever formed. See
      !! emit_grad_class/emit_dc_vrr in scripts/gen_1e.py.
      !!
      !! gc is intent(inout) and ADDED into, never zeroed here, on
      !! purpose: the caller passes a slice of its own lane-private
      !! accumulator directly (trc_1e_grad_driver.inc's one_e_grad_item),
      !! not a per-thread local -- an automatic array sized by the RUNTIME
      !! value `natm` inside a `!$acc routine seq` body needs a per-thread
      !! dynamic stack allocation that a large `natm` (a 60-atom cluster,
      !! say) under thousands of concurrently resident threads overruns,
      !! which is exactly a CUDA_ERROR_LAUNCH_FAILED "invalid pointer
      !! dereference" and not a Fortran-level bug. Measured: that is what
      !! one_e_grad_item's own gc(3,natm) local used to be, and it is why
      !! this kernel does not get one either.
      !$acc routine seq
      integer,  intent(in)  :: nprim_a, nprim_b, natm
      real(dp), intent(in)  :: ea(nprim_a), ca(nprim_a)
      real(dp), intent(in)  :: eb(nprim_b), cb(nprim_b)
      real(dp), intent(in)  :: ra(3), rb(3)
      real(dp), intent(in)  :: zatm(natm), ratm(3, natm)
      real(dp), intent(in)  :: wt, wblk(3), dblk(3)
      real(dp), intent(out)   :: ga(3), gb(3)
      real(dp), intent(inout) :: gc(3, natm)

      integer  :: ip, jp, ic, k
      real(dp) :: al, bet, zeta, oo2z, xi, cc, tbb
      real(dp) :: px, py, pz, pax, pay, paz, pbx, pby, pbz
      real(dp) :: pcx, pcy, pcz, tval, vpref, rab2
      real(dp) :: abx, aby, abz, e0x, e0y, e0z
      real(dp) :: sx(0:1,0:3), sy(0:1,0:3), sz(0:1,0:3)
      real(dp) :: tx(0:1,0:1), ty(0:1,0:1), tz(0:1,0:1)
      real(dp) :: vn(10,0:2), vn0(10)
      real(dp) :: wx(4,0:1), wy(4,0:1), wz(4,0:1)
      real(dp) :: wx0(4), wy0(4), wz0(4)
      real(dp) :: vAp(9)
      real(dp) :: vBp(6)
      real(dp) :: vBm(1)
      real(dp) :: wxt(3), wyt(3), wzt(3)
      real(dp) :: f(0:BOYS_MMAX)

      abx = ra(1) - rb(1); aby = ra(2) - rb(2); abz = ra(3) - rb(3)
      rab2 = abx*abx + aby*aby + abz*abz

      ga = 0.0_dp; gb = 0.0_dp

      do ip = 1, nprim_a
         al = ea(ip)
      do jp = 1, nprim_b
         bet = eb(jp)
         zeta = al + bet
         oo2z = 0.5_dp/zeta
         xi = al*bet/zeta
         cc = ca(ip)*cb(jp)*wt
         tbb = 2.0_dp*bet*bet

         px = (al*ra(1) + bet*rb(1))/zeta
         py = (al*ra(2) + bet*rb(2))/zeta
         pz = (al*ra(3) + bet*rb(3))/zeta
         pax = px - ra(1); pay = py - ra(2); paz = pz - ra(3)
         pbx = px - rb(1); pby = py - rb(2); pbz = pz - rb(3)

         e0x = sqrt(PI/zeta)*exp(-xi*abx*abx)
         e0y = sqrt(PI/zeta)*exp(-xi*aby*aby)
         e0z = sqrt(PI/zeta)*exp(-xi*abz*abz)

         sx(0,0) = e0x
         sx(1,0) = pax*sx(0,0)
         sx(0,1) = pbx*sx(0,0)
         sx(1,1) = pbx*sx(1,0) + 1.0_dp*oo2z*sx(0,0)
         sx(0,2) = pbx*sx(0,1) + 1.0_dp*oo2z*sx(0,0)
         sx(1,2) = pbx*sx(1,1) + 1.0_dp*oo2z*sx(0,1) + 1.0_dp*oo2z*sx(1,0)
         sx(0,3) = pbx*sx(0,2) + 2.0_dp*oo2z*sx(0,1)
         sx(1,3) = pbx*sx(1,2) + 1.0_dp*oo2z*sx(0,2) + 2.0_dp*oo2z*sx(1,1)
         sy(0,0) = e0y
         sy(1,0) = pay*sy(0,0)
         sy(0,1) = pby*sy(0,0)
         sy(1,1) = pby*sy(1,0) + 1.0_dp*oo2z*sy(0,0)
         sy(0,2) = pby*sy(0,1) + 1.0_dp*oo2z*sy(0,0)
         sy(1,2) = pby*sy(1,1) + 1.0_dp*oo2z*sy(0,1) + 1.0_dp*oo2z*sy(1,0)
         sy(0,3) = pby*sy(0,2) + 2.0_dp*oo2z*sy(0,1)
         sy(1,3) = pby*sy(1,2) + 1.0_dp*oo2z*sy(0,2) + 2.0_dp*oo2z*sy(1,1)
         sz(0,0) = e0z
         sz(1,0) = paz*sz(0,0)
         sz(0,1) = pbz*sz(0,0)
         sz(1,1) = pbz*sz(1,0) + 1.0_dp*oo2z*sz(0,0)
         sz(0,2) = pbz*sz(0,1) + 1.0_dp*oo2z*sz(0,0)
         sz(1,2) = pbz*sz(1,1) + 1.0_dp*oo2z*sz(0,1) + 1.0_dp*oo2z*sz(1,0)
         sz(0,3) = pbz*sz(0,2) + 2.0_dp*oo2z*sz(0,1)
         sz(1,3) = pbz*sz(1,2) + 1.0_dp*oo2z*sz(0,2) + 2.0_dp*oo2z*sz(1,1)

         tx(0,0) = 1.0_dp*bet*sx(0,0) - tbb*sx(0,2)
         tx(1,0) = 1.0_dp*bet*sx(1,0) - tbb*sx(1,2)
         tx(0,1) = 3.0_dp*bet*sx(0,1) - tbb*sx(0,3)
         tx(1,1) = 3.0_dp*bet*sx(1,1) - tbb*sx(1,3)
         ty(0,0) = 1.0_dp*bet*sy(0,0) - tbb*sy(0,2)
         ty(1,0) = 1.0_dp*bet*sy(1,0) - tbb*sy(1,2)
         ty(0,1) = 3.0_dp*bet*sy(0,1) - tbb*sy(0,3)
         ty(1,1) = 3.0_dp*bet*sy(1,1) - tbb*sy(1,3)
         tz(0,0) = 1.0_dp*bet*sz(0,0) - tbb*sz(0,2)
         tz(1,0) = 1.0_dp*bet*sz(1,0) - tbb*sz(1,2)
         tz(0,1) = 3.0_dp*bet*sz(0,1) - tbb*sz(0,3)
         tz(1,1) = 3.0_dp*bet*sz(1,1) - tbb*sz(1,3)

         ga(1) = ga(1) - cc*wblk(1)*((2.0_dp*al*sx(1,1))*sy(0,0)*sz(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*tx(1,1))*sy(0,0)*sz(0,0) + (2.0_dp*al*sx(1,1))*(ty(0,0)*sz(0,0) + sy(0,0)*tz(0,0)))
         gb(1) = gb(1) + cc*wblk(1)*((2.0_dp*al*sx(1,1))*sy(0,0)*sz(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*tx(1,1))*sy(0,0)*sz(0,0) + (2.0_dp*al*sx(1,1))*(ty(0,0)*sz(0,0) + sy(0,0)*tz(0,0)))
         ga(2) = ga(2) - cc*wblk(1)*((2.0_dp*al*sy(1,0))*sx(0,1)*sz(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*ty(1,0))*sx(0,1)*sz(0,0) + (2.0_dp*al*sy(1,0))*(tx(0,1)*sz(0,0) + sx(0,1)*tz(0,0)))
         gb(2) = gb(2) + cc*wblk(1)*((2.0_dp*al*sy(1,0))*sx(0,1)*sz(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*ty(1,0))*sx(0,1)*sz(0,0) + (2.0_dp*al*sy(1,0))*(tx(0,1)*sz(0,0) + sx(0,1)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(1)*((2.0_dp*al*sz(1,0))*sx(0,1)*sy(0,0)) &
                         + cc*dblk(1)*((2.0_dp*al*tz(1,0))*sx(0,1)*sy(0,0) + (2.0_dp*al*sz(1,0))*(tx(0,1)*sy(0,0) + sx(0,1)*ty(0,0)))
         gb(3) = gb(3) + cc*wblk(1)*((2.0_dp*al*sz(1,0))*sx(0,1)*sy(0,0)) &
                         - cc*dblk(1)*((2.0_dp*al*tz(1,0))*sx(0,1)*sy(0,0) + (2.0_dp*al*sz(1,0))*(tx(0,1)*sy(0,0) + sx(0,1)*ty(0,0)))
         ga(1) = ga(1) - cc*wblk(2)*((2.0_dp*al*sx(1,0))*sy(0,1)*sz(0,0)) &
                         + cc*dblk(2)*((2.0_dp*al*tx(1,0))*sy(0,1)*sz(0,0) + (2.0_dp*al*sx(1,0))*(ty(0,1)*sz(0,0) + sy(0,1)*tz(0,0)))
         gb(1) = gb(1) + cc*wblk(2)*((2.0_dp*al*sx(1,0))*sy(0,1)*sz(0,0)) &
                         - cc*dblk(2)*((2.0_dp*al*tx(1,0))*sy(0,1)*sz(0,0) + (2.0_dp*al*sx(1,0))*(ty(0,1)*sz(0,0) + sy(0,1)*tz(0,0)))
         ga(2) = ga(2) - cc*wblk(2)*((2.0_dp*al*sy(1,1))*sx(0,0)*sz(0,0)) &
                         + cc*dblk(2)*((2.0_dp*al*ty(1,1))*sx(0,0)*sz(0,0) + (2.0_dp*al*sy(1,1))*(tx(0,0)*sz(0,0) + sx(0,0)*tz(0,0)))
         gb(2) = gb(2) + cc*wblk(2)*((2.0_dp*al*sy(1,1))*sx(0,0)*sz(0,0)) &
                         - cc*dblk(2)*((2.0_dp*al*ty(1,1))*sx(0,0)*sz(0,0) + (2.0_dp*al*sy(1,1))*(tx(0,0)*sz(0,0) + sx(0,0)*tz(0,0)))
         ga(3) = ga(3) - cc*wblk(2)*((2.0_dp*al*sz(1,0))*sx(0,0)*sy(0,1)) &
                         + cc*dblk(2)*((2.0_dp*al*tz(1,0))*sx(0,0)*sy(0,1) + (2.0_dp*al*sz(1,0))*(tx(0,0)*sy(0,1) + sx(0,0)*ty(0,1)))
         gb(3) = gb(3) + cc*wblk(2)*((2.0_dp*al*sz(1,0))*sx(0,0)*sy(0,1)) &
                         - cc*dblk(2)*((2.0_dp*al*tz(1,0))*sx(0,0)*sy(0,1) + (2.0_dp*al*sz(1,0))*(tx(0,0)*sy(0,1) + sx(0,0)*ty(0,1)))
         ga(1) = ga(1) - cc*wblk(3)*((2.0_dp*al*sx(1,0))*sy(0,0)*sz(0,1)) &
                         + cc*dblk(3)*((2.0_dp*al*tx(1,0))*sy(0,0)*sz(0,1) + (2.0_dp*al*sx(1,0))*(ty(0,0)*sz(0,1) + sy(0,0)*tz(0,1)))
         gb(1) = gb(1) + cc*wblk(3)*((2.0_dp*al*sx(1,0))*sy(0,0)*sz(0,1)) &
                         - cc*dblk(3)*((2.0_dp*al*tx(1,0))*sy(0,0)*sz(0,1) + (2.0_dp*al*sx(1,0))*(ty(0,0)*sz(0,1) + sy(0,0)*tz(0,1)))
         ga(2) = ga(2) - cc*wblk(3)*((2.0_dp*al*sy(1,0))*sx(0,0)*sz(0,1)) &
                         + cc*dblk(3)*((2.0_dp*al*ty(1,0))*sx(0,0)*sz(0,1) + (2.0_dp*al*sy(1,0))*(tx(0,0)*sz(0,1) + sx(0,0)*tz(0,1)))
         gb(2) = gb(2) + cc*wblk(3)*((2.0_dp*al*sy(1,0))*sx(0,0)*sz(0,1)) &
                         - cc*dblk(3)*((2.0_dp*al*ty(1,0))*sx(0,0)*sz(0,1) + (2.0_dp*al*sy(1,0))*(tx(0,0)*sz(0,1) + sx(0,0)*tz(0,1)))
         ga(3) = ga(3) - cc*wblk(3)*((2.0_dp*al*sz(1,1))*sx(0,0)*sy(0,0)) &
                         + cc*dblk(3)*((2.0_dp*al*tz(1,1))*sx(0,0)*sy(0,0) + (2.0_dp*al*sz(1,1))*(tx(0,0)*sy(0,0) + sx(0,0)*ty(0,0)))
         gb(3) = gb(3) + cc*wblk(3)*((2.0_dp*al*sz(1,1))*sx(0,0)*sy(0,0)) &
                         - cc*dblk(3)*((2.0_dp*al*tz(1,1))*sx(0,0)*sy(0,0) + (2.0_dp*al*sz(1,1))*(tx(0,0)*sy(0,0) + sx(0,0)*ty(0,0)))

         ! --- nuclear attraction: basis derivative + Hellmann-Feynman, per nucleus ---
         vpref = 2.0_dp*PI/zeta*exp(-xi*rab2)
         do ic = 1, natm
            pcx = px - ratm(1, ic)
            pcy = py - ratm(2, ic)
            pcz = pz - ratm(3, ic)
            tval = zeta*(pcx*pcx + pcy*pcy + pcz*pcz)
            call boys_eval(2, tval, f)

            ! --- m = 2 ---
            vn(1,2) = vpref*f(2)
            ! --- m = 1 ---
            vn(1,1) = vpref*f(1)
            vn(2,1) = pax*vn(1,1) - pcx*vn(1,2)
            vn(3,1) = pay*vn(1,1) - pcy*vn(1,2)
            vn(4,1) = paz*vn(1,1) - pcz*vn(1,2)
            ! --- m = 0 ---
            vn(1,0) = vpref*f(0)
            vn(2,0) = pax*vn(1,0) - pcx*vn(1,1)
            vn(3,0) = pay*vn(1,0) - pcy*vn(1,1)
            vn(4,0) = paz*vn(1,0) - pcz*vn(1,1)
            vn(5,0) = pax*vn(2,0) - pcx*vn(2,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(6,0) = pax*vn(3,0) - pcx*vn(3,1)
            vn(7,0) = pax*vn(4,0) - pcx*vn(4,1)
            vn(8,0) = pay*vn(3,0) - pcy*vn(3,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))
            vn(9,0) = pay*vn(4,0) - pcy*vn(4,1)
            vn(10,0) = paz*vn(4,0) - pcz*vn(4,1) &
               + 1.0_dp*oo2z*(vn(1,0) - vn(1,1))

            ! --- dV/dC, m = 1 ---
            wx(1,1) = 2.0_dp*zeta*pcx*vn(1,2)
            wy(1,1) = 2.0_dp*zeta*pcy*vn(1,2)
            wz(1,1) = 2.0_dp*zeta*pcz*vn(1,2)
            ! --- dV/dC, m = 0 ---
            wx(1,0) = 2.0_dp*zeta*pcx*vn(1,1)
            wy(1,0) = 2.0_dp*zeta*pcy*vn(1,1)
            wz(1,0) = 2.0_dp*zeta*pcz*vn(1,1)
            wx(2,0) = pax*wx(1,0) - pcx*wx(1,1) &
               + vn(1,1)
            wy(2,0) = pax*wy(1,0) - pcx*wy(1,1)
            wz(2,0) = pax*wz(1,0) - pcx*wz(1,1)
            wx(3,0) = pay*wx(1,0) - pcy*wx(1,1)
            wy(3,0) = pay*wy(1,0) - pcy*wy(1,1) &
               + vn(1,1)
            wz(3,0) = pay*wz(1,0) - pcy*wz(1,1)
            wx(4,0) = paz*wx(1,0) - pcz*wx(1,1)
            wy(4,0) = paz*wy(1,0) - pcz*wy(1,1)
            wz(4,0) = paz*wz(1,0) - pcz*wz(1,1) &
               + vn(1,1)

            do k = 1, 10
               vn0(k) = vn(k,0)
            end do
            do k = 1, 4
               wx0(k) = wx(k,0); wy0(k) = wy(k,0); wz0(k) = wz(k,0)
            end do

            vAp(1) = abx*vn0(2) &
               + vn0(5)
            vAp(2) = abx*vn0(3) &
               + vn0(6)
            vAp(3) = abx*vn0(4) &
               + vn0(7)
            vAp(4) = aby*vn0(2) &
               + vn0(6)
            vAp(5) = aby*vn0(3) &
               + vn0(8)
            vAp(6) = aby*vn0(4) &
               + vn0(9)
            vAp(7) = abz*vn0(2) &
               + vn0(7)
            vAp(8) = abz*vn0(3) &
               + vn0(9)
            vAp(9) = abz*vn0(4) &
               + vn0(10)

            ! la = 0: no (la-1,lb) class

            vBp(1) = abx*abx*vn0(1) &
               + 2.0_dp*abx*vn0(2) &
               + vn0(5)
            vBp(2) = abx*aby*vn0(1) &
               + abx*vn0(3) &
               + aby*vn0(2) &
               + vn0(6)
            vBp(3) = abx*abz*vn0(1) &
               + abx*vn0(4) &
               + abz*vn0(2) &
               + vn0(7)
            vBp(4) = aby*aby*vn0(1) &
               + 2.0_dp*aby*vn0(3) &
               + vn0(8)
            vBp(5) = aby*abz*vn0(1) &
               + aby*vn0(4) &
               + abz*vn0(3) &
               + vn0(9)
            vBp(6) = abz*abz*vn0(1) &
               + 2.0_dp*abz*vn0(4) &
               + vn0(10)

            vBm(1) = vn0(1)

            wxt(1) = abx*wx0(1) &
               + wx0(2)
            wxt(2) = aby*wx0(1) &
               + wx0(3)
            wxt(3) = abz*wx0(1) &
               + wx0(4)

            wyt(1) = abx*wy0(1) &
               + wy0(2)
            wyt(2) = aby*wy0(1) &
               + wy0(3)
            wyt(3) = abz*wy0(1) &
               + wy0(4)

            wzt(1) = abx*wz0(1) &
               + wz0(2)
            wzt(2) = aby*wz0(1) &
               + wz0(3)
            wzt(3) = abz*wz0(1) &
               + wz0(4)

            ga(1) = ga(1) - cc*zatm(ic)*dblk(1)*(2.0_dp*al*vAp(1))
            gb(1) = gb(1) - cc*zatm(ic)*dblk(1)*(2.0_dp*bet*vBp(1) - 1.0_dp*vBm(1))
            !$acc atomic update
            gc(1,ic) = gc(1,ic) - cc*zatm(ic)*dblk(1)*wxt(1)
            ga(2) = ga(2) - cc*zatm(ic)*dblk(1)*(2.0_dp*al*vAp(2))
            gb(2) = gb(2) - cc*zatm(ic)*dblk(1)*(2.0_dp*bet*vBp(2))
            !$acc atomic update
            gc(2,ic) = gc(2,ic) - cc*zatm(ic)*dblk(1)*wyt(1)
            ga(3) = ga(3) - cc*zatm(ic)*dblk(1)*(2.0_dp*al*vAp(3))
            gb(3) = gb(3) - cc*zatm(ic)*dblk(1)*(2.0_dp*bet*vBp(3))
            !$acc atomic update
            gc(3,ic) = gc(3,ic) - cc*zatm(ic)*dblk(1)*wzt(1)
            ga(1) = ga(1) - cc*zatm(ic)*dblk(2)*(2.0_dp*al*vAp(4))
            gb(1) = gb(1) - cc*zatm(ic)*dblk(2)*(2.0_dp*bet*vBp(2))
            !$acc atomic update
            gc(1,ic) = gc(1,ic) - cc*zatm(ic)*dblk(2)*wxt(2)
            ga(2) = ga(2) - cc*zatm(ic)*dblk(2)*(2.0_dp*al*vAp(5))
            gb(2) = gb(2) - cc*zatm(ic)*dblk(2)*(2.0_dp*bet*vBp(4) - 1.0_dp*vBm(1))
            !$acc atomic update
            gc(2,ic) = gc(2,ic) - cc*zatm(ic)*dblk(2)*wyt(2)
            ga(3) = ga(3) - cc*zatm(ic)*dblk(2)*(2.0_dp*al*vAp(6))
            gb(3) = gb(3) - cc*zatm(ic)*dblk(2)*(2.0_dp*bet*vBp(5))
            !$acc atomic update
            gc(3,ic) = gc(3,ic) - cc*zatm(ic)*dblk(2)*wzt(2)
            ga(1) = ga(1) - cc*zatm(ic)*dblk(3)*(2.0_dp*al*vAp(7))
            gb(1) = gb(1) - cc*zatm(ic)*dblk(3)*(2.0_dp*bet*vBp(3))
            !$acc atomic update
            gc(1,ic) = gc(1,ic) - cc*zatm(ic)*dblk(3)*wxt(3)
            ga(2) = ga(2) - cc*zatm(ic)*dblk(3)*(2.0_dp*al*vAp(8))
            gb(2) = gb(2) - cc*zatm(ic)*dblk(3)*(2.0_dp*bet*vBp(5))
            !$acc atomic update
            gc(2,ic) = gc(2,ic) - cc*zatm(ic)*dblk(3)*wyt(3)
            ga(3) = ga(3) - cc*zatm(ic)*dblk(3)*(2.0_dp*al*vAp(9))
            gb(3) = gb(3) - cc*zatm(ic)*dblk(3)*(2.0_dp*bet*vBp(6) - 1.0_dp*vBm(1))
            !$acc atomic update
            gc(3,ic) = gc(3,ic) - cc*zatm(ic)*dblk(3)*wzt(3)
         end do
      end do
      end do
   end subroutine one_e_grad_01

